import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

// Official DataLife Account Logo (base64 embedded — works without server)
const LOGO_SRC = "data:image/jpeg;base64,";

const SIZE_MAP = {
  small:   { width: 120 },
  default: { width: 180 },
  large:   { width: 220 },
  xlarge:  { width: 280 },
};

const CompanyLogo = ({ size = 'default', className = '', style = {} }) => {
  const { width } = SIZE_MAP[size] || SIZE_MAP.default;
  return (
    <img
      src={LOGO_SRC}
      alt="DataLife Account"
      width={width}
      style={{ maxWidth: width, height: 'auto', objectFit: 'contain', ...style }}
      className={className}
    />
  );
};

export default CompanyLogo;
